// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address actor, uint256 newVal) public {
        vm.assume(actor != address(0));
        newVal = bound(newVal, 0, type(uint256).max);

        // finalize the contract
        vm.prank(actor);
        c.Initialized();

        // invariant: once finalized, SetMinSum must revert for ANY caller/value
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "SetMinSum must revert after Initialized()");
    }
}
